import{_ as l,o as e,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-08-22 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-08-22 -- Ceph Performance Meeting","date":"2019-08-22T00:00:00.000Z","updated":"2019-09-06T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","基准测试","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-08-22_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-08-22_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-08-22_-_-_Ceph_Performance_Meeting.md"};function o(a,i,s,_,p,g){return e(),t("div",null,[...i[0]||(i[0]=[r("<p>2019年8月22日，Ceph项目团队召开了一次性能会议，讨论了Ceph分布式存储项目的进展、讨论的主要议题、决定的事项以及后续的行动计划。</p><p><strong>会议内容</strong>：</p><ul><li><strong>项目进展</strong>： <ul><li>已合并的Pull Requests (PR) 包括增加East Heart缓冲区大小至64K，Sage的64K Yarn调整等。</li><li>待处理的PR包括Casey关于扩展LTTE Angie跟踪点的PR，Alec关于64K大小的Yarn的PR，Sam关于扩展LTTE Angie跟踪点的PR，雷达后端复制的PR，Ken Adams的PR，调整MVS缓存内存限制的PR，分布式数据缓存RGW的PR等。</li><li>其他进展包括Igor更新了新的较小版本的Blue Store，Eager功能正在开发中，Sam的PR旨在扩展LTTE Angie跟踪点，雷达后端的PR已通过审查，MVS缓存内存限制的调整PR仍在进行中，分布式数据缓存RGW的PR由Mark Hogan负责。</li></ul></li><li><strong>讨论议题</strong>： <ul><li><strong>新的S3基准测试</strong>： 讨论了新的S3基准测试，旨在提供一个轻量级、快速、易于使用的工具，以展示Ceph的功能。</li><li><strong>桶重组</strong>： 讨论了桶重组的性能问题，特别是关于CPU使用率和延迟的问题。</li><li><strong>对象存储优化</strong>： 讨论了对象存储优化，特别是关于减少写放大和空间放大的问题。</li></ul></li><li><strong>决定事项</strong>： <ul><li>将继续开发新的S3基准测试。</li><li>将继续优化桶重组和对象存储。</li><li>将审查和合并待处理的PR。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>继续开发新的S3基准测试。</li><li>优化桶重组和对象存储。</li><li>审查和合并待处理的PR。</li></ul></li></ul><p><strong>会议中提到的关键词</strong>：</p><ul><li>Ceph</li><li>Blue Store</li><li>Eager</li><li>LTTE Angie</li><li>OSD</li><li>RGW</li><li>S3</li><li>T-rex DB</li><li>RocksDB</li><li>Rados</li><li>PG</li><li>PG log</li><li>PG info</li><li>CLS</li><li>CLS igw</li><li>OMAP</li><li>Write amplification</li><li>Space amplification</li></ul><p>改进后的总结更准确地反映了原始内容的要点，包括会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。同时，保留了计算机科学/ceph相关领域的英文原文关键词，以便读者更好地理解会议内容。</p>",6)])])}const u=l(n,[["render",o]]);export{c as __pageData,u as default};
